import{_ as t,a,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 50 He likes ... but he does not like ...","description":"学习 第三人称单数与 does，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 50 He likes ... but he does not like ...","description":"学习 第三人称单数与 does，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 第三人称单数与 does，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 49 At the butcher's","link":"/life/english/new-concept/book-1/unit-03/lesson-049"},"next":{"text":"第一册：英语初阶 · Lesson 51 A pleasant climate","link":"/life/english/new-concept/book-1/unit-03/lesson-051"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 49 At the butcher's","link":"/life/english/new-concept/book-1/unit-03/lesson-049"},"next":{"text":"第一册：英语初阶 · Lesson 51 A pleasant climate","link":"/life/english/new-concept/book-1/unit-03/lesson-051"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-050.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-050.md"}`),n={name:"life/english/new-concept/book-1/unit-03/lesson-050.md"};function r(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-lesson-50-he-likes-but-he-does-not-like" tabindex="-1">第一册：英语初阶 · Lesson 50 He likes ... but he does not like ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-50-he-likes-but-he-does-not-like" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 50 He likes ... but he does not like ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-049">配套课 Lesson 49</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>购买食物时表达家人的喜好 本课要掌握第三人称单数与 does，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>beef</td><td>/biːf/</td><td>n.</td><td>牛肉</td><td>some beef</td></tr><tr><td>chicken</td><td>/ˈtʃɪkɪn/</td><td>n.</td><td>鸡肉</td><td>roast chicken</td></tr><tr><td>butcher</td><td>/ˈbʊtʃə/</td><td>n.</td><td>肉商</td><td>at the butcher&#39;s</td></tr><tr><td>prefer</td><td>/prɪˈfɜː/</td><td>v.</td><td>更喜欢</td><td>prefer fish</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>does not like — 助动词后恢复原形</li><li>at the butcher&#39;s — 在肉店，省略 shop</li></ul><h2 id="语法讲解-第三人称单数与-does" tabindex="-1">语法讲解：第三人称单数与 does <a class="header-anchor" href="#语法讲解-第三人称单数与-does" aria-label="Permalink to &quot;语法讲解：第三人称单数与 does&quot;">​</a></h2><p>一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Does your daughter eat carrots?</p></blockquote><p>你女儿吃胡萝卜吗？</p><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Does she eats? 中 eats 应改为 eat；第三人称变化只保留在 does。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Does your daughter eat carrots?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Does your daughter eat carrots? My brother prefers fish to beef.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“购买食物时表达家人的喜好”写两至三句，再读给同伴听。至少使用一次第三人称单数与 does，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。 My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填原形：Does she ___ (eat) carrots?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eat</p><p><strong>解析：</strong> 按本课规则判断：一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“你女儿吃胡萝卜吗？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Does your daughter eat carrots?</p><p><strong>解析：</strong> Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：My brother prefers fish to beef.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我哥哥喜欢鱼胜过牛肉。</p><p><strong>解析：</strong> My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：第三人称单数与 does。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-051">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(n,[["render",r]]);export{p as __pageData,b as default};
